import csv
import io


def parse_csv(text, delimiter=","):
    """Parse Dasel's header-row CSV representation into a list of maps."""
    if not text:
        return []
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
    try:
        rows = list(reader)
    except csv.Error as exc:
        raise ValueError(str(exc)) from exc
    if not rows:
        return []
    headers = rows[0]
    result = []
    for row_no, row in enumerate(rows[1:], 2):
        # encoding/csv's reader ignores physically blank records.
        if not row:
            continue
        if len(row) != len(headers):
            raise ValueError(f"record on line {row_no}: wrong number of fields")
        # Assignment order intentionally gives the last duplicate header precedence.
        result.append(dict(zip(headers, row)))
    return result


def write_csv(value, delimiter=","):
    """Serialize an array of maps as CSV, requiring consistent map keys."""
    if not isinstance(value, list):
        if value is None:
            kind = "null"
        elif isinstance(value, dict):
            kind = "map"
        elif isinstance(value, str):
            kind = "string"
        elif isinstance(value, bool):
            kind = "bool"
        elif isinstance(value, int):
            kind = "int"
        elif isinstance(value, float):
            kind = "float"
        else:
            kind = type(value).__name__
        raise TypeError(f"csv writer expects root output to be a slice/array, got {kind}")
    if not value:
        return ""
    if not isinstance(value[0], dict):
        raise TypeError("error ranging slice: error getting map keys")
    headers = list(value[0].keys())
    buf = io.StringIO(newline="")
    writer = csv.writer(buf, delimiter=delimiter, lineterminator="\n")
    writer.writerow(headers)
    for item in value:
        if not isinstance(item, dict):
            raise TypeError("error ranging slice: error getting map keys")
        cells = []
        for key in headers:
            if key not in item:
                raise ValueError(f'error ranging slice: error getting map key "{key}": map key not found: "{key}"')
            cell = item[key]
            if isinstance(cell, (dict, list)):
                kind = "map" if isinstance(cell, dict) else "array"
                raise ValueError(f"error ranging slice: error converting value to string: csv writer cannot format type {kind} to string")
            cells.append(_csv_scalar(cell))
        writer.writerow(cells)
    return buf.getvalue()


def _csv_scalar(value):
    if value is None:
        return ""
    if isinstance(value, (dict, list)):
        return str(value)
    if value is True:
