"""KDL writer for the JSON-like data model."""
import json
import re


_TOKEN = re.compile(r'\s+|//[^\n]*|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[{};]|[^\s{};]+')


def _scalar(token):
    if token.startswith('"') and token.endswith('"'):
        try: return json.loads(token)
        except Exception: return token[1:-1]
    if token.startswith("'") and token.endswith("'"): return token[1:-1]
    if token == '#true': return True
    if token == '#false': return False
    if token == '#null': return None
    try: return json.loads(token)
    except Exception: return token


def parse_kdl(text):
    if not text.strip(): return None
    tokens = []
    for token in _TOKEN.findall(text):
        if token.isspace() or token.startswith('//'):
            if '\n' in token: tokens.append('\n')
            continue
        tokens.append(token)
    pos = 0

    def add(target, key, value):
        if key in target:
            if isinstance(target[key], list): target[key].append(value)
            else: target[key] = [target[key], value]
        else: target[key] = value

    def nodes(target, nested=False):
        nonlocal pos
        while pos < len(tokens):
            while pos < len(tokens) and tokens[pos] in ('\n', ';'): pos += 1
            if pos >= len(tokens): return
            if tokens[pos] == '}':
                if nested: pos += 1
                return
            if tokens[pos] == '{':
                pos += 1
                continue
            name = _scalar(tokens[pos]); pos += 1
            args, props = [], {}
            while pos < len(tokens) and tokens[pos] not in ('\n', ';', '{', '}'):
                token = tokens[pos]; pos += 1
                if '=' in token:
                    k, v = token.split('=', 1)
                    props[str(_scalar(k))] = _scalar(v)
                else: args.append(_scalar(token))
            children = {}
            if pos < len(tokens) and tokens[pos] == '{':
                pos += 1
                nodes(children, True)
            if children:
                value = children
                if args: value['$args'] = args
                value.update(props)
            elif props:
                value = {}
                if args: value['$args'] = args
                value.update(props)
            elif len(args) == 1: value = args[0]
            elif args: value = {'$args': args}
            else: value = ''
            add(target, str(name), value)
            if pos < len(tokens) and tokens[pos] == '}':
                if nested: pos += 1
                return
    result = {}
    nodes(result)
    return result


def _name(s):
    s = str(s)
    return s if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_-]*", s) else json.dumps(s, ensure_ascii=False)


def _arg(v):
    if v is None: return ""
    if v is True: return "#true"
    if v is False: return "#false"
    if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
    return str(v)


def dump_kdl(value, compact=False):
    lines = []
    def node(name, value, indent=0):
        pad = " " * indent
        if isinstance(value, dict):
            scalar = [(k, v) for k, v in value.items() if not isinstance(v, (dict, list))]
            children = [(k, v) for k, v in value.items() if isinstance(v, (dict, list))]
            head = pad + _name(name)
            for k, v in scalar:
                head += " " + _name(k) + "=" + _arg(v)
            if children:
                lines.append(head + " {")
                for k, v in children:
                    if isinstance(v, list):
                        for item in v:
                            if isinstance(item, dict):
                                node(k, item, indent + 2)
                            elif isinstance(item, list):
                                node(k, item, indent + 2)
                            else:
                                lines.append(" " * (indent + 2) + _name(k) + (" " + _arg(item) if item is not None else ""))
                    else:
                        node(k, v, indent + 2)
                lines.append(pad + "}")
            else:
                lines.append(head)
        elif isinstance(value, list):
            args = "".join(" " + _arg(x) for x in value if not isinstance(x, (dict, list)) and x is not None)
            maps = [x for x in value if isinstance(x, dict)]
            if maps:
                for m in maps:
                    head = pad + _name(name)
                    for k, v in m.items():
                        if not isinstance(v, (dict, list)): head += " " + _name(k) + "=" + _arg(v)
                    kids = [(k, v) for k, v in m.items() if isinstance(v, (dict, list))]
                    if kids:
                        lines.append(head + " {")
                        for k, v in kids: node(k, v, indent + 2)
                        lines.append(pad + "}")
                    else: lines.append(head)
            elif args:
                lines.append(pad + _name(name) + args)
        else:
            lines.append(pad + _name(name) + (" " + _arg(value) if value is not None else ""))

    if isinstance(value, dict):
        for k, v in value.items():
            if isinstance(v, list):
                for item in v:
                    if isinstance(item, dict): node(k, item)
                    elif isinstance(item, list): node(k, item)
                    else: node(k, item)
            else: node(k, v)
    elif isinstance(value, (list, str, int, float, bool)) or value is None:
        node("root", value)
    if compact:
        out=[]; depth=0
        for line in lines:
            part=line.strip()
            if part.endswith("{"):
                out.append(part[:-1].rstrip()+"{"); depth+=1
            elif part == "}":
                out.append("}"); depth=max(0,depth-1)
            elif part:
                out.append(part+(";" if depth else ""))
        return "".join(out)
    return "\n".join(lines) + ("\n" if lines else "")
